    helper='''    private String displayClientName(JSONObject p){String n=p.optString("name","").trim(),a=p.optString("surname","").trim();String full=(n+" "+a).trim();if(!full.isEmpty()&&!looksLikeOcr(full))return full;String h=p.optString("holder","").trim();return(!h.isEmpty()&&!looksLikeOcr(h))?h:"Cliente sin nombre";}\n    private boolean looksLikeOcr(String x){String u=x.toUpperCase(Locale.ROOT);return u.contains("DOCUMENTO")||u.contains("NNAOONAL")||u.contains("NACIONAL ESP");}\n'''
